/**
 * The membership row for (org, user) whether or not it has been removed. A
 * removed member keeps the same row, so a rejoin must find it here rather than
 * insert a second one.
 */
export async function findMemberRecord(
  orgId: OrgId,
  userId: UserId,
): Promise<Member | null> {
  const row = getDb()
    .select()
    .from(members)
    .where(and(orgPredicate(members.orgId, orgId), eq(members.userId, userId)))
    .get();
  return row ? toMember(row) : null;
}

/** A membership that is live the moment it is written: accepting is joining. */
export async function insertMember(
  orgId: OrgId,
  userId: UserId,
  role: Role,
  invitedBy: UserId | null,
): Promise<Member> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(members)
    .values({
      id: newId(),
      orgId,
      userId,
      role,
      status: "active",
      invitedBy,
      joinedAt: stamp,
      lastSeenAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toMember(row);
}

/**
 * Brings a removed member back on the same row: live again, with the role,
 * inviter and join date of the invitation that was accepted.
 */
export async function restoreMember(
  orgId: OrgId,
  memberId: MemberId,
  role: Role,
  invitedBy: UserId | null,
  joinedAt: IsoTimestamp,
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({
      ...restorePatch(new Date(joinedAt)),
      role,
      status: "active",
      invitedBy,
      joinedAt,
    })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

  if (!row) throw new Error(`Member ${memberId} not found in org ${orgId}`);
  return toMember(row);
}

