cat > tests/services/zz-scratch-verify.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { hashToken } from "@/lib/hash";
import { getDb, invitations } from "@/server/db";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as invitationService from "@/server/services/invitation-service";
import * as memberService from "@/server/services/member-service";
import * as orgService from "@/server/services/organization-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("scratch", () => {
  it("full lifecycle", async () => {
    const t = await createTenant("scratch-life", "growth");
    const org = t.org.id;

    // expiry is 14 days
    const [inv] = await invitationService.inviteMembers(t.actors.admin, {
      orgId: org, invites: [{ email: "Pat@Scratch.test", role: "viewer" }],
    });
    const days = (new Date(inv!.expiresAt).getTime() - Date.now()) / 86400000;
    expect(Math.round(days)).toBe(14);

    // duplicate (case-insensitive) pending refused, batch with dup refused w/o writes
    await expect(invitationService.inviteMember(t.actors.admin, { orgId: org, email: "pat@scratch.test", role: "member" })).rejects.toThrow(/pending/);
    const before = await invitationRepo.countPendingInvitations(org);
    await expect(invitationService.inviteMembers(t.actors.admin, { orgId: org, invites: [
      { email: "x@scratch.test", role: "member" }, { email: "X@scratch.test", role: "member" } ] })).rejects.toThrow(/more than once/);
    expect(await invitationRepo.countPendingInvitations(org)).toBe(before);

    // existing member refused
    await expect(invitationService.inviteMember(t.actors.admin, { orgId: org, email: t.users?.member ?? "", role: "member" })).rejects.toThrow();

    // wrong account refused, invite stays pending
    const other = await userRepo.insertUser({ email: "other@scratch.test", name: "O", passwordHash: "x" });
    const token = "t".repeat(32);
    await invitationRepo.insertInvitation(org, { orgId: org, email: "pat@scratch.test", role: "viewer", expiresInDays: 14 }, t.userIds.admin, hashToken(token));
    await expect(invitationService.acceptInvitation(other.id, { token })).rejects.toThrow(/different email/);

    // correct account accepts; active + listed + usable
    const pat = await userRepo.insertUser({ email: "pat@scratch.test", name: "P", passwordHash: "x" });
    const m = await invitationService.acceptInvitation(pat.id, { token });
    expect(m.status).toBe("active");
    expect(await memberRepo.countActiveMembers(org)).toBe(5);
    // used up
    await expect(invitationService.acceptInvitation(pat.id, { token })).rejects.toThrow(/already been accepted/);

    // remove, session defaulting, notify filtering
    const session = await sessionRepo.createSession(pat.id, hashToken("s".repeat(32)), new Date(Date.now()+86400000).toISOString() as any);
    await sessionRepo.setActiveOrg(session.userId as any, org); // not used; setActiveOrg takes sessionId
    await memberService.removeMember(t.actors.owner, { orgId: org, memberId: m.id });
    expect(await memberRepo.findMember(org, pat.id)).toBeNull();

    // rejoin via new invitation -> same member id, new role
    const [again] = await invitationService.inviteMembers(t.actors.admin, { orgId: org, invites: [{ email: "pat@scratch.test", role: "admin" }] });
    const token2 = "u".repeat(32);
    await invitationRepo.revokeInvitation(org, again!.id);
    await invitationRepo.insertInvitation(org, { orgId: org, email: "pat@scratch.test", role: "admin", expiresInDays: 14 }, t.userIds.owner, hashToken(token2));
    const rejoined = await invitationService.acceptInvitation(pat.id, { token: token2 });
    expect(rejoined.id).toBe(m.id);
    expect(rejoined.role).toBe("admin");
    expect(rejoined.invitedBy).toBe(t.userIds.owner);
    expect(await memberRepo.countActiveMembers(org)).toBe(5);

    // deleted org refuses accept
    const [inv2] = await invitationService.inviteMembers(t.actors.admin, { orgId: org, invites: [{ email: "late@scratch.test", role: "member" }] });
    void inv2;
  });

  it("resend keeps role and works on expired", async () => {
    const t = await createTenant("scratch-resend", "growth");
    const org = t.org.id;
    const row = await invitationRepo.insertInvitation(org, { orgId: org, email: "ex@scratch.test", role: "viewer", expiresInDays: -1 }, t.userIds.admin, hashToken("e".repeat(32)));
    const re = await invitationService.resendInvitation(t.actors.admin, row.id);
    expect(re.role).toBe("viewer");
    expect(re.email).toBe("ex@scratch.test");
    expect(await invitationRepo.countPendingInvitations(org)).toBe(1);
    await expect(invitationService.acceptInvitation((await userRepo.insertUser({ email: "ex@scratch.test", name: "E", passwordHash: "x" })).id, { token: "e".repeat(32) })).rejects.toThrow(/expired|revoked/);
  });

  it("deleted org refuses accept and clears sessions", async () => {
    const t = await createTenant("scratch-del", "growth");
    const org = t.org.id;
    const u = await userRepo.insertUser({ email: "gone@scratch.test", name: "G", passwordHash: "x" });
    const tok = "d".repeat(32);
    await invitationRepo.insertInvitation(org, { orgId: org, email: "gone@scratch.test", role: "member", expiresInDays: 14 }, t.userIds.admin, hashToken(tok));
    await orgService.deleteOrganization(t.actors.owner, { orgId: org, confirmSlug: t.org.slug } as any);
    await expect(invitationService.acceptInvitation(u.id, { token: tok })).rejects.toThrow(/deleted/);
  });
});
EOF
